def warning_text(category: str | None, language: str = "en-IN") -> tuple[str, str]:
    """Return (text, language actually used)."""
    lang = language if language in WARNINGS else "en-IN"
    texts = WARNINGS[lang]
    return texts.get(category or "", texts["default"]), lang
